router.beforeEach(async (to, _from, next) => {
  // Remove template store from localStorage if route does not contain '/page-builder'
  if (!to.path.includes('/page-builder')) {
    // Pinia-plugin-persistedstate defaults to the store id as the key.
    // Some older setups use a 'pinia-' prefix; clear both defensively.
    try {
      localStorage.removeItem('template');
      localStorage.removeItem('pinia-template');
    } catch {
      /* Ignore storage errors */
    }
  }
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }

  const userAuth = useProfileStore();

  if (to.meta.requiresAuth) {
    try {
      await userAuth.authenticateUser();
      const user = await userAuth.getUser();

      if (user) {
        await userAuth.authorizeUser();
        await userAuth.fetchUserAttributes();
        return next();
      }

      appLogger.error('User not found');
      return next('/unauthorized');
    } catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      return next('/unauthorized');
    }
  }

  return next();
});

