import { createI18n } from 'vue-i18n';
import en from './locales/en.json';
import fr from './locales/fr.json';

/**
 * Export a global i18n instance that can be used by stores and non-setup code.
 * Import { i18n } and use i18n.global.t(...) when outside of a component setup.
 */
export const i18n = createI18n({
