/**
 * Base API URL for BOM reporting endpoints
 */
let token = import.meta.env.TOKEN;
token = token === 'PING_FEDERATE' ? sessionStorage.getItem('id_token') : token;
const adminUrl = import.meta.env.ADMIN_BACKEND_URL;

/**
 * Service for BOM reporting API operations
 */
class BomReportingService {
  /**
   * Fetches material options for dropdown selection
   * @param plant - The plant ID to fetch materials for
   * @returns Promise with array of material options
   */
  public static async getMaterialsByPlantId(
    plant: number,
  ): Promise<Array<Material>> {
    try {
      const response: AxiosResponse<Array<Material>> = await axios.get(
        `${adminUrl}/admin/getAllMaterial/${plant}`,
        {
          headers: {
            authorization: `Bearer ${token}`,
          },
        },
      );

      return response.data;
    } catch (error) {
      console.error('Failed to get materials by plant ID', error);
      throw error;
    }
  }

  /**
   * Fetches BOM data based on filter criteria
   * @param parameters - The query parameters containing material ID, plant, and optional filters
   * @returns Promise with BOM data
   */
  public static async getBOMWithComponents(
    parameters: GetBOMQueryParametersDTO,
  ): Promise<BOMResponseDTO> {
    try {
      const requestBody = {
        erpBomId: parameters.erpBomId ?? undefined, // Use erpBomId consistently
        includeComponents: parameters.includeComponents ?? true,
        materialId: parameters.materialId,
        plant: parameters.plant,
        validityDate: parameters.validityDate
          ? parameters.validityDate.toISOString() // Keep full ISO string with date and time
          : undefined,
      };

      const response = await axios.post<BOMResponseDTO>(
        `${adminUrl}/boms/get-boms`,
        requestBody,
        {
          headers: {
            authorization: `Bearer ${token}`,
          },
        },
      );

      return response.data;
    } catch (error) {
      appLogger.error(
        `Error fetching BOM data: ${error instanceof Error ? error.message : String(error)}`,
      );
      throw error;
    }
  }

  /**
   * Searches for BOMs using advanced search criteria
   * @param parameters - Search parameters for BOMs
   * @returns Promise with a list of BOMs matching the search criteria
   */
  public static async searchBOMs(
    parameters: GetBOMsByBomIdDTO,
  ): Promise<Array<BOMListItemDTO>> {
    try {
      const requestBody = {
        erpBomId: parameters.erpBomId,
        validityDate: parameters.validFrom
          ? parameters.validFrom.toISOString()
          : undefined, // Keep full ISO string with date and time
        plant: parameters.plant,
      };

      // Define interface for the API response structure
      interface GetBOMsResponseDTO {
        boms: Array<BOMListItemDTO>;
      }

      const response = await axios.post<GetBOMsResponseDTO>(
        `${adminUrl}/boms/get-erp-boms`,
        requestBody,
        {
          headers: {
            authorization: `Bearer ${token}`,
          },
        },
      );

      // Extract the boms array from the response
      appLogger.debug(`BOM search response: ${JSON.stringify(response.data)}`);
      return response.data.boms || [];
    } catch (error) {
      appLogger.error(
        `Error searching BOMs: ${error instanceof Error ? error.message : String(error)}`,
      );
      throw error;
    }
  }

  /**
   * Updates the kitmat and skipBomLevel flags for components
   * @param updateDto - The update request with components to update
   * @returns Promise with update response
   */
  public static async updateComponentFlags(
    updateDto: UpdateBOMComponentsRequestDTO,
  ): Promise<UpdateBOMComponentsResponseDTO> {
    try {
      // Format the request without erpBomId as per API requirements
      const formattedRequest = {
        components: updateDto.components, // Keep the numeric component IDs
      };

      appLogger.debug(
        `Updating components with request: ${JSON.stringify(formattedRequest)}`,
      );

      const response = await axios.put<UpdateBOMComponentsResponseDTO>(
        `${adminUrl}/boms/update-components`,
        formattedRequest,
        {
          headers: {
            authorization: `Bearer ${token}`,
          },
        },
      );
      return response.data;
    } catch (error) {
      appLogger.error(
        `Error updating component flags for BOM ${updateDto.erpBomId}: ${error instanceof Error ? error.message : String(error)}`,
      );
      throw error;
    }
  }
}

