import { defineStore } from 'pinia';
import { Notify } from 'quasar';
import { ref, reactive } from 'vue';
import {
  BOMResponseDTO,
  BOMComponentResponseDTO,
  GetBOMQueryParametersDTO,
  UpdateComponentFlagDTO,
  UpdateBOMComponentsRequestDTO,
  BOMListItemDTO,
  GetBOMsByBomIdDTO,
} from '../dto/bom.dto';
import { bomReportingService } from '../service/bom-reporting.service';
import { Material } from '@/models/material.model';
import { useProfileStore } from '@/store/user-auth-store';
import appLogger from '@/utils/logger/app-logger';

export const useBomReportingStore = defineStore('bomReporting', () => {
  // State
  const loading = ref(false);
  const bomData = ref<BOMResponseDTO | undefined>(undefined);
  const bomFilter = reactive<GetBOMQueryParametersDTO>({
    materialId: '',
    plant: 0, // This will be set from the user's profile
  });

  /**
   * Sets filter criteria for BOM data retrieval
   * @param filter - The filter criteria to apply
   */
  function setFilter(filter: Partial<GetBOMQueryParametersDTO>): void {
    Object.assign(bomFilter, filter);
  }

  const expandedComponents = ref<Array<string>>([]);
  const kitmatValues = reactive<Record<string, boolean>>({});
  const originalKitmatValues = reactive<Record<string, boolean>>({});
  const skipBomLevelValues = reactive<Record<string, boolean>>({});
  const originalSkipBomLevelValues = reactive<Record<string, boolean>>({});
  const componentIdMap = reactive<Record<string, number>>({});
  const selectedMaterialId = ref<string | undefined>(undefined);

  const materialOptions = ref<Array<Material>>([]);

  // State for BOM search
  const bomSearchResults = ref<Array<BOMListItemDTO>>([]);
  const bomSearchLoading = ref(false);

  /**
   * Initializes kitmat and skipBomLevel values from loaded BOM data
   */
  function initializeKitmatValues(): void {
    if (bomData.value?.components) {
      // Reset the component ID mapping
      for (const key of Object.keys(componentIdMap)) {
        delete componentIdMap[key];
      }

      const processComponents = (
        components: Array<BOMComponentResponseDTO>,
      ): void => {
        for (const component of components) {
          // Use the numeric ID from the API response instead of the component name
          const componentKey = component.component;
          // Store the mapping between component name and actual ID
          componentIdMap[componentKey] = component.id;

          kitmatValues[componentKey] = Boolean(component.kitmat);
          originalKitmatValues[componentKey] = Boolean(component.kitmat);
          skipBomLevelValues[componentKey] = Boolean(component.skipBomLevel);
          originalSkipBomLevelValues[componentKey] = Boolean(
            component.skipBomLevel,
          );

          // Process sub-components if they exist
          if (component.subComponents && component.subComponents.length > 0) {
            processComponents(component.subComponents);
          }
        }
      };

      processComponents(bomData.value.components);
    }
  }

  // Actions
  /**
   * Loads material options for dropdown selection
   * @returns Promise that resolves when loading is complete
   */
  async function loadMaterialOptions(): Promise<void> {
    const userAttributesStore = useProfileStore();
    try {
      loading.value = true;
      const plantId = Number(userAttributesStore.userAttributes.plant);
      const materials =
        await bomReportingService.getMaterialsByPlantId(plantId);

      // Update material options with the correct model properties
      materialOptions.value = materials;
    } catch (error) {
      appLogger.error(
        `Error loading materials: ${error instanceof Error ? error.message : String(error)}`,
      );
      Notify.create({
        type: 'negative',
        message: 'Failed to load material options',
        position: 'top',
        timeout: 2000,
      });
      // Set empty array to avoid undefined issues
      materialOptions.value = [];
    } finally {
      loading.value = false;
    }
  }

  /**
   * Resets the expanded components
   */
  function resetExpanded(): void {
    expandedComponents.value = [];
  }

  /**
   * Searches for BOMs based on search criteria
   * @param searchParameters - The search parameters to use for BOM search
   * @returns Promise that resolves when search is complete
   */
  async function searchBOMs(
    searchParameters: GetBOMsByBomIdDTO,
  ): Promise<boolean> {
    try {
      bomSearchLoading.value = true;

      const results = await bomReportingService.searchBOMs(searchParameters);
      bomSearchResults.value = results;

      return true;
    } catch (error) {
      console.error('Error searching BOMs:', error);
      Notify.create({
        type: 'negative',
        message: 'Failed to search BOMs',
        position: 'top',
        timeout: 2000,
      });
      bomSearchResults.value = [];
      return false;
    } finally {
      bomSearchLoading.value = false;
    }
  }

  /**
   * Fetches BOM data based on filter criteria
   * @returns Promise that resolves when data is fetched
   */
  async function fetchBomData(): Promise<void> {
    const userAttributesStore = useProfileStore();
    if (!bomFilter.materialId) {
      bomData.value = undefined;
      return;
    }

    try {
      loading.value = true;

      // Create a clean filter object with only the populated properties
      const queryParameters: GetBOMQueryParametersDTO = {
        materialId: bomFilter.materialId,
        plant: Number(userAttributesStore.userAttributes.plant),
      };

      // Only add optional parameters if they have values
      if (bomFilter.erpBomId) {
        queryParameters.erpBomId = bomFilter.erpBomId;
      }

      if (bomFilter.validityDate) {
        queryParameters.validityDate =
          bomFilter.validityDate instanceof Date
            ? bomFilter.validityDate
            : new Date(bomFilter.validityDate);
      }

      bomData.value =
        await bomReportingService.getBOMWithComponents(queryParameters);
      initializeKitmatValues();
      resetExpanded();
    } catch (error) {
      console.error('Error fetching BOM data:', error);
      Notify.create({
        type: 'negative',
        message: 'Failed to fetch BOM data',
        position: 'top',
        timeout: 2000,
      });
      bomData.value = undefined;
    } finally {
      loading.value = false;
    }
  }

  /**
   * Loads a specific BOM from search results
   * @param bom - The selected BOM to load
   * @returns Promise that resolves when data is fetched
   */
  async function loadBOM(bom: BOMListItemDTO): Promise<void> {
    // Update the selected material ID
    selectedMaterialId.value = bom.materialId;

    // Update filter with the selected BOM details, using the correct parameter name
    setFilter({
      materialId: bom.materialId,
      erpBomId: bom.erpBomId, // Use erpBomId consistently
      validityDate: new Date(bom.validFrom),
    });

    // Fetch the BOM data using the updated filter
    await fetchBomData();
  }

  /**
   * Toggles the expansion of a component to show its sublevels
   * @param componentId - ID of the component to toggle
   */
  function toggleSublevels(componentId: string): void {
    if (expandedComponents.value.includes(componentId)) {
      // Collapse
      expandedComponents.value = expandedComponents.value.filter(
        (id) => id !== componentId,
      );
    } else {
      // Expand - the BOM already includes all nested components so we just toggle the visibility
      expandedComponents.value.push(componentId);
    }
  }

  /**
   * Toggles the kitmat value for a component
   * @param componentId - ID of the component to toggle
   */
  function toggleKitmatValue(componentId: string): void {
    kitmatValues[componentId] = !kitmatValues[componentId];
  }

  /**
   * Toggles the skipBomLevel value for a component
   * @param componentId - ID of the component to toggle
   */
  function toggleSkipBomLevelValue(componentId: string): void {
    skipBomLevelValues[componentId] = !skipBomLevelValues[componentId];
  }

  /**
   * Collects components that have changed their kitmat or skipBomLevel values
   * @returns Array of components with their updated values
   */
  function collectChangedComponents(): Array<UpdateComponentFlagDTO> {
    const changedComponents: Array<UpdateComponentFlagDTO> = [];

    for (const componentKey of Object.keys(kitmatValues)) {
      const kitmatChanged =
        kitmatValues[componentKey] !== originalKitmatValues[componentKey];
      const skipBomLevelChanged =
        skipBomLevelValues[componentKey] !==
        originalSkipBomLevelValues[componentKey];

      if (kitmatChanged || skipBomLevelChanged) {
        const numericId = componentIdMap[componentKey];
        if (numericId) {
          changedComponents.push({
            componentId: numericId,
            kitmat: kitmatValues[componentKey],
            skipBomLevel: skipBomLevelValues[componentKey],
          });
        } else {
          console.warn(
            `Could not find numeric ID for component ${componentKey}`,
          );
        }
      }
    }

    return changedComponents;
  }

  /**
   * Updates original values after successful save
   * @param components - The components that were successfully updated
   */
  function updateOriginalValues(
    components: Array<UpdateComponentFlagDTO>,
  ): void {
    for (const component of components) {
      const componentKey = Object.keys(componentIdMap).find(
        (key) => componentIdMap[key] === component.componentId,
      );

      if (componentKey) {
        originalKitmatValues[componentKey] = component.kitmat;
        originalSkipBomLevelValues[componentKey] = component.skipBomLevel;
      }
    }
  }

  /**
   * Saves all changes to kitmat and skipBomLevel values
   * @returns Promise that resolves when all changes are saved
   */
  async function saveAllChanges(): Promise<boolean> {
    if (!bomData.value) return false;

    const changedComponents = collectChangedComponents();
    if (changedComponents.length === 0) return true;

    try {
      loading.value = true;

      const updateRequest: UpdateBOMComponentsRequestDTO = {
        erpBomId: bomData.value.erpBomId,
        components: changedComponents,
      };

      appLogger.debug(`Saving changes for BOM: ${bomData.value.erpBomId}`);
      appLogger.debug(
        `Changed components: ${JSON.stringify(changedComponents)}`,
      );

      const response =
        await bomReportingService.updateComponentFlags(updateRequest);

      if (response.success) {
        updateOriginalValues(changedComponents);

        Notify.create({
          type: 'positive',
          message: 'Changes saved successfully',
          position: 'top',
          timeout: 2000,
        });

        return true;
      }
      throw new Error(response.message || 'Failed to update component flags');
    } catch (error) {
      console.error('Error saving changes:', error);
      Notify.create({
        type: 'negative',
        message:
          error instanceof Error ? error.message : 'Failed to save changes',
        position: 'top',
        timeout: 2000,
      });
      return false;
    } finally {
      loading.value = false;
    }
  }

  /**
   * Resets all changes to kitmat and skipBomLevel values to their original state
   */
  function resetChanges(): void {
    for (const componentId of Object.keys(originalKitmatValues)) {
      kitmatValues[componentId] = originalKitmatValues[componentId];
    }

    for (const componentId of Object.keys(originalSkipBomLevelValues)) {
      skipBomLevelValues[componentId] = originalSkipBomLevelValues[componentId];
    }
  }

  /**
   * Checks if there are any unsaved changes to kitmat or skipBomLevel values
   * @returns True if there are unsaved changes, false otherwise
   */
  function hasUnsavedChanges(): boolean {
    const hasKitmatChanges = Object.keys(kitmatValues).some(
      (componentId) =>
        kitmatValues[componentId] !== originalKitmatValues[componentId],
    );

    const hasSkipBomLevelChanges = Object.keys(skipBomLevelValues).some(
      (componentId) =>
        skipBomLevelValues[componentId] !==
        originalSkipBomLevelValues[componentId],
    );

    return hasKitmatChanges || hasSkipBomLevelChanges;
  }

  /**
   * Clears the BOM search results
   */
  function clearBOMSearchResults(): void {
    bomSearchResults.value = [];
  }

  // Return store properties and methods
  return {
    // State
    bomData,
    bomFilter,
    bomSearchLoading,
    bomSearchResults,
    expandedComponents,
    kitmatValues,
    loading,
    materialOptions,
    originalKitmatValues,
    originalSkipBomLevelValues,
    selectedMaterialId, // Add the selectedMaterialId to the returned store properties
    skipBomLevelValues,

    // Actions
    clearBOMSearchResults,
    fetchBomData,
    hasUnsavedChanges,
    initializeKitmatValues,
    loadBOM,
    loadMaterialOptions,
    resetChanges,
    resetExpanded,
    saveAllChanges,
    searchBOMs,
    setFilter,
    toggleKitmatValue,
    toggleSkipBomLevelValue,
    toggleSublevels,
  };
});

