import { ref } from 'vue';

/**
 * Composable for handling assignment dialog state and actions.
 * @returns Assignment dialog state and handlers.
 */
export function useAssignDialog(): {
  assignDialogOpen: ReturnType<typeof ref<boolean>>;
  assignInitialResourceIds: ReturnType<typeof ref<Array<string>>>;
  handleApply: (ids: Array<string>) => void;
  handleCancel: () => void;
  openAssignDialog: (initialIds?: Array<string>) => Promise<Array<string>>;
} {
  // Always ensure assignDialogOpen is boolean, never undefined
  const assignDialogOpen = ref<boolean>(false);
  // Defensive: always set to false, never undefined
  // Removed unused setAssignDialogOpen function
  const assignInitialResourceIds = ref<Array<string>>([]);
  const assignPromise = ref<undefined | ((ids: Array<string>) => void)>(
    undefined,
  );

  /**
   * Opens the assignment dialog.
   * @param initialIds Initial resource IDs to pre-select.
   * @returns Promise resolving with selected IDs.
   */
  function openAssignDialog(
    initialIds: Array<string> = [],
  ): Promise<Array<string>> {
    assignInitialResourceIds.value = initialIds;
    assignDialogOpen.value = true;
    return new Promise((resolve) => {
      assignPromise.value = resolve;
    });
  }

  /**
   * Handles apply action in dialog.
   * @param ids Selected resource IDs.
   */
  function handleApply(ids: Array<string>): void {
    assignDialogOpen.value = false;
    if (assignPromise.value) {
      assignPromise.value(ids);
      assignPromise.value = undefined;
    }
  }

  /**
   * Handles cancel action in dialog.
   */
  function handleCancel(): void {
    assignDialogOpen.value = false;
    if (assignPromise.value) {
      assignPromise.value([]);
      assignPromise.value = undefined;
    }
  }

  return {
    assignDialogOpen,
    assignInitialResourceIds,
    handleApply,
    handleCancel,
    openAssignDialog,
  };
}

import { getTemplatesByPlant } from '../services/template-api';
import { useTemplateStore } from '../store/template-store';
import { useProfileStore } from '@/store/user-auth-store';

/**
 * Composable for publish warning logic.
 * @returns Publish warning checker.
 */
export interface PublishScopeConflict {
  resourceId: string;
  templateLabel: string;
}
/**
 * Composable for publish warning logic.
 * @returns Publish warning checker with conflict detection functionality.
 */
export function usePublishWarning(): {
  checkAlreadyAssignedOnPublish: () => Promise<Array<PublishScopeConflict>>;
} {
  const templateStore = useTemplateStore();
  const profileStore = useProfileStore();

  /**
   * Checks if selected resources are already assigned to other published templates.
   * @returns All detected resource/template conflicts.
   */
  async function checkAlreadyAssignedOnPublish(): Promise<
    Array<PublishScopeConflict>
  > {
    const plantId = Number(profileStore.userAttributes?.plant);
    if (!plantId) return [];

    const currentScopeList = templateStore.template.scopeList || [];
    if (currentScopeList.length === 0) return [];

    const selectedResourceIds = new Set(
      currentScopeList
        .filter(
          (scope) =>
            String(scope?.scopeType ?? '').toUpperCase() === 'RESOURCE',
        )
        .map((scope) => String(scope?.scopeValue ?? '').trim())
        .filter((id) => id.length > 0),
    );
    if (selectedResourceIds.size === 0) return [];

    const templates = await getTemplatesByPlant(plantId);

    const conflictsByResource = new Map<string, PublishScopeConflict>();
    for (const tpl of templates) {
      const isCurrentTemplate =
        String(tpl.id ?? '') === String(templateStore.template.id ?? '');
      const isPublished =
        String(tpl.status ?? '').toLowerCase() === 'published';
      if (!isCurrentTemplate && isPublished) {
        const tplResourceIds = (tpl.scopeList ?? [])
          .filter(
            (scope) =>
              String(scope?.scopeType ?? '').toUpperCase() === 'RESOURCE',
          )
          .map((scope) => String(scope?.scopeValue ?? '').trim())
          .filter((id) => id.length > 0);

        for (const id of tplResourceIds) {
          if (selectedResourceIds.has(id) && !conflictsByResource.has(id)) {
            conflictsByResource.set(id, {
              resourceId: id,
              templateLabel:
                String(tpl.label ?? '').trim() || 'Another template',
            });
          }
        }
      }
    }

    return [...conflictsByResource.values()];
  }

  return { checkAlreadyAssignedOnPublish };
}

