/**
 * Generates a unique identifier for page-builder entities.
 * @param prefix The prefix to include in the generated id.
 * @returns The generated identifier string.
 */
function newId(prefix = 'id'): string {
  const rand = Math.random().toString(16).slice(2);
  const time = Date.now().toString(16);
  return `${prefix}_${time}_${rand}`;
}

/**
 * Coerces a value to a lower-cased string.
 * @param value The value to coerce.
 * @returns The lower-cased string when possible; otherwise an empty string.
 */
function coerceLowerString(value: unknown): string {
  if (typeof value === 'string') return value.toLowerCase();
  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value).toLowerCase();
  }
  return '';
}

/**
 * Coerces a value into a trimmed string.
 * @param value The value to coerce.
 * @returns The trimmed string when possible; otherwise an empty string.
 */
function coerceTrimmedString(value: unknown): string {
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value).trim();
  }
  return '';
}

/**
 * Coerces a value to a template status.
 * @param value The value to coerce.
 * @returns The normalized template status.
 */
function coerceTemplateStatus(value: unknown): 'draft' | 'published' {
  const normalized = coerceLowerString(value);
  return normalized === 'published' ? 'published' : 'draft';
}

/**
 * Normalizes a screen ID.
 * @param id The raw screen id.
 * @returns The normalized screen id.
 */
function normalizeScreenId(id: number): number {
  return id;
}

/**
 * Infers the number of columns from widget positions.
 * @param widgets The widgets to analyze.
 * @returns The inferred columns count.
 */
function inferColumnsCountFromWidgets(
  widgets: Array<{ position?: string }> | undefined,
): 1 | 2 | 3 {
  const positions = new Set(
    (widgets ?? []).map((w) => coerceLowerString(w.position)).filter(Boolean),
  );
  if (positions.has('middle')) return 3;
  if (positions.has('left') || positions.has('right')) return 2;
  return 1;
}

/**
 * Maps a widget position to a column index.
 * @param columnsCount The number of columns.
 * @param position The raw widget position.
 * @returns The 0-based column index.
 */
function positionToColumnIndex(
  columnsCount: 1 | 2 | 3,
  position: unknown,
): number {
  const p = coerceLowerString(position);
  if (columnsCount === 1) return 0;
  if (columnsCount === 2) return p === 'right' ? 1 : 0;
  if (p === 'right') return 2;
  if (p === 'middle') return 1;
  return 0;
}

type ScreenCatalogItem = TemplateScreen & { enabled: boolean };

// Catalog of screens shown in the "Create new template" modal.
// Disabled entries are visible but cannot be selected.
