// ComponentData type for widget/component definitions
export interface ComponentData {
  apiLink: string;
  apiMethod: string;
  apiParams: Record<string, unknown>;
  appListId: Array<string>;
  code: string;
  configSchema: Record<string, unknown>;
  description: string;
  id: number;
  label: string;
  scopeId: Array<string>;
  showLabel?: boolean;
  size: string;
  value: unknown;
}

interface BuilderLayout {
  width: number;
  height: number;
  sections: Array<Section>;
  minSection?: number;
  maxSection?: number;
}

/**
 * Derives a semantic widget position name from a column index.
 * @param columnsCount Total columns in the section.
 * @param columnIndex The current column index.
 * @returns The semantic position.
 */
function getSemanticWidgetPosition(
  columnsCount: number,
  columnIndex: number,
): 'left' | 'middle' | 'right' | 'full' {
  if (columnsCount <= 1) return 'full';
  if (columnsCount === 2) return columnIndex === 0 ? 'left' : 'right';
  if (columnIndex === 0) return 'left';
  if (columnIndex === columnsCount - 1) return 'right';
  return 'middle';
}

/**
 * Converts a column count into the component size expected by the backend.
 * @param columnsCount Total columns in the section.
 * @returns The component size.
 */
function getComponentSizeFromColumns(
  columnsCount: number,
): 'full' | 'half' | 'third' {
  if (columnsCount <= 1) return 'full';
  if (columnsCount === 2) return 'half';
  return 'third';
}

/**
 * Flattens section widgets into the backend widget DTO list.
 * @param section The section to flatten.
 * @param widgetApiLookup Lookup map of widget definitions.
 * @returns The flattened widgets list.
 */
function flattenWidgets(
  section: Section,
  widgetApiLookup: Record<string, { widget: ComponentData }>,
): Array<WidgetDto> {
  const widgets: Array<WidgetDto> = [];
  const columns = Array.isArray(section.columns) ? section.columns : [];
  const columnsCount = columns.length;
  const componentSize = getComponentSizeFromColumns(columnsCount);
  let order = 0;
  for (const [columnIndex, col] of columns.entries()) {
    const placedWidgets = Array.isArray(col.widgets) ? col.widgets : [];
    for (const placed of placedWidgets) {
      const key = placed.defId;
      const component = widgetApiLookup[key]?.widget;
      widgets.push({
        component: {
          api: component?.apiLink ?? '',
          code: component?.code ?? '',
          configSchema: component?.configSchema ?? {},
          label: component?.label ?? '',
          showLabel: Boolean(component?.showLabel),
          size: componentSize,
        },
        configSchema: {},
        id: `widget_${order}`,
        label: placed.title || component?.label || '',
        order,
        // Derive from UI column position.
        position: getSemanticWidgetPosition(columnsCount, columnIndex),
      });
      order += 1;
    }
  }
  return widgets;
}

export const useTemplateStore = defineStore(
  'template',
  () => {
    // --- State ---
    const template = ref<PageBuilderTemplate>(createDefaultTemplate());
    const screenCatalog = ref<Array<ScreenCatalogItem>>(
      TEMPLATE_SCREENS_CATALOG.map((s) => ({ ...s })),
    );
    // Sort-keys: devices before screens, status before updatedBy
    const availableScreens = computed<Array<TemplateScreen>>(() =>
      screenCatalog.value.map((s) => ({
        screenId: s.screenId,
        screenName: s.screenName,
      })),
    );
    const NEW_TEMPLATE_SEED_KEY = 'pb.newTemplateSeed';
    const newTemplateSeed = ref<
      | {
          plantId: number;
          screenOptionId: string;
        }
      | undefined
    >(undefined);

    // Load seed from localStorage if present
    const storedSeed = localStorage.getItem(NEW_TEMPLATE_SEED_KEY);
    if (storedSeed) {
      try {
        const parsed = JSON.parse(storedSeed);
        if (
          parsed &&
          typeof parsed.plantId === 'number' &&
          typeof parsed.screenOptionId === 'string'
        ) {
          newTemplateSeed.value = parsed;
        }
      } catch {
        // Ignore JSON parse errors
      }
    }
    // Store the template DTO selected for editing (bypassing broken API)
    const templateToEdit = ref<TemplateDto | undefined>(undefined);
    const components = ref<Array<ComponentData>>([]); // Widget/component definitions
    const loading = ref(false);
    const error = ref<string | undefined>(undefined);

    interface TemplateScreenOption {
      id: string;
      label: string;
      screens: Array<TemplateScreen>;
      disabled: boolean;
    }

    /**
     * Finds a catalog item by screen ID.
     * @param sid The screen ID.
     * @returns The ScreenCatalogItem if found.
     */
    function catalogItemById(sid: number): ScreenCatalogItem | undefined {
      return screenCatalog.value.find(
        (s) => normalizeScreenId(s.screenId) === sid,
      );
    }

    // Some screens must share the same template (single selection => multiple screens).
    // Add more groups here as needed.
    const TEMPLATE_SCREEN_GROUPS: Array<{
      id: string;
      screenIds: Array<number>;
    }> = [{ id: 'edashboard-live-status', screenIds: [32, 33] }];

    const screenOptions = computed<Array<TemplateScreenOption>>(() => {
      const options: Array<TemplateScreenOption> = [];
      const used = new Set<number>();

      for (const group of TEMPLATE_SCREEN_GROUPS) {
        const groupItems = group.screenIds
          .map((sid: number) => catalogItemById(sid))
          .filter(Boolean);

        const screens = groupItems
          .filter(
            (item): item is ScreenCatalogItem =>
              item !== undefined && 'enabled' in item,
          )
          .map((s) => ({ screenId: s.screenId, screenName: s.screenName }));

        if (screens.length > 0) {
          for (const s of screens) used.add(normalizeScreenId(s.screenId));

          const disabled = groupItems.some(
            (x) => x !== undefined && 'enabled' in x && !x.enabled,
          );

          const label = screens
            .map((s) =>
              (
                coerceTrimmedString(s.screenName) ||
                String(normalizeScreenId(s.screenId))
              ).trim(),
            )
            .filter(Boolean)
            .join(' / ');

          options.push({
            id: `group:${group.id}`,
            label: label || group.id,
            screens,
            disabled,
          });
        }
      }

      for (const item of screenCatalog.value) {
        const sid = normalizeScreenId(item.screenId);
        if (!used.has(sid)) {
          options.push({
            id: `screen:${sid}`,
            label:
              (coerceTrimmedString(item.screenName) || String(sid)).trim() ||
              String(sid),
            screens: [{ screenId: item.screenId, screenName: item.screenName }],
            disabled: !item.enabled,
          });
        }
      }

      return options;
    });

    /**
     * Resolves available screens for a given option ID.
     * @param optionId The ID of the screen option to resolve.
     * @returns The array of TemplateScreen objects for the option.
     */
    function resolveScreensForOptionId(
      optionId: string,
    ): Array<TemplateScreen> {
      const found = screenOptions.value.find((o) => o.id === optionId);
      if (found) return found.screens;

      // Back-compat: if caller passes raw screenId
      const raw = optionId.startsWith('screen:')
        ? optionId.slice('screen:'.length)
        : optionId;

      const rawAsNumber = Number(raw);
      const rawNumber = Number.isNaN(rawAsNumber) ? undefined : rawAsNumber;
      const byId = screenCatalog.value.find(
        (s) => normalizeScreenId(s.screenId) === rawNumber,
      );
      return byId ? [byId] : [];
    }

    // --- Internal utility ---
    // Helper: get sections array from desktop layout, with defensive initialization
    /**
     * Ensures that the desktop layout exists and is normalized.
     * @returns The normalized desktop layout.
     */
    function ensureDesktopLayout(): BuilderLayout {
      if (!template.value.devices) {
        template.value.devices = {
          desktop: { resolution: '1920*1080', layout: {} },
          mobile: { resolution: '', layout: {} },
          tablet: { resolution: '', layout: {} },
        };
      }
      if (!template.value.devices.desktop) {
        template.value.devices.desktop = {
          resolution: '1920*1080',
          layout: {},
        };
      }
      if (!template.value.devices.desktop.layout) {
        template.value.devices.desktop.layout = {};
      }

      const layout = template.value.devices.desktop.layout as unknown as
        | Partial<BuilderLayout>
        | undefined;

      // --- Ensure minSection and maxSection are always present ---
      const width = typeof layout?.width === 'number' ? layout.width : 788;
      const height = typeof layout?.height === 'number' ? layout.height : 929;
      const minSection =
        typeof layout?.minSection === 'number' ? layout.minSection : 3;
      const maxSection =
        typeof layout?.maxSection === 'number' ? layout.maxSection : 4;

      if (!layout || !Array.isArray(layout.sections)) {
        const next: BuilderLayout & { minSection: number; maxSection: number } =
          {
            height,
            maxSection,
            minSection,
            sections: [],
            width,
          };
        template.value.devices.desktop.layout =
          next as unknown as PageBuilderTemplate['devices']['desktop']['layout'];
        return next;
      }

      const normalized: BuilderLayout & {
        minSection: number;
        maxSection: number;
      } = {
        height,
        maxSection,
        minSection,
        sections: layout.sections,
        width,
      };
      template.value.devices.desktop.layout =
        normalized as unknown as PageBuilderTemplate['devices']['desktop']['layout'];
      return normalized;
    }

    /**
     * Reads the current desktop sections list.
     * @returns The section array.
     */
    function getSections(): Array<Section> {
      return ensureDesktopLayout().sections;
    }

    /**
     * Writes the current desktop sections list.
     * @param sections The next section array.
     */
    function setSections(sections: Array<Section>): void {
      const layout = ensureDesktopLayout();
      // Keep section.order consistent with UI order.
      for (const [index, section] of sections.entries()) {
        section.order = index;
      }
      const next: BuilderLayout = {
        height: layout.height,
        maxSection: layout.maxSection,
        minSection: layout.minSection,
        sections,
        width: layout.width,
      };
      template.value.devices.desktop.layout =
        next as unknown as PageBuilderTemplate['devices']['desktop']['layout'];
    }

    // Map widget code to widget data
    const widgetApiMap = computed(() => {
      const map: Record<string, { widget: ComponentData }> = {};
      for (const c of components.value) {
        map[c.code] = { widget: c };
      }
      return map;
    });

    // --- Internal utility ---
    /**
     * Submits the current template to the backend.
     * @param status The desired template status.
     * @returns Whether the request succeeded and the updated template payload.
     */
    async function submitTemplate(
      status: 'draft' | 'published',
    ): Promise<{ success: boolean; payload?: PageBuilderTemplate }> {
      loading.value = true;
      error.value = undefined;
      try {
        const profileStore = useProfileStore();
        const plant = Number(profileStore.userAttributes?.plant);
        if (!Number.isFinite(plant)) {
          throw new TypeError('Plant is missing from user attributes');
        }
        const width = 788;
        const height = 929;
        const sections = getSections();
        const layout = {
          configSchema: {},
          height,
          id: 'desktop',
          maxSection: 4,
          minSection: 3,
          sections: (sections ?? []).map((s, index) => ({
            configSchema: writeSideGroupIdToConfigSchema(
              (s as { configSchema?: unknown })?.configSchema,
              s.sideGroupId,
            ),
            id: `section_${index}`,
            label: s.label,
            maxWidget: 0,
            // Always derive from current UI layout order.
            minWidget: 0,
            order: index,
            widgets: flattenWidgets(s, widgetApiMap.value),
          })),
          width,
        };
        const devices = {
          desktop: {
            layout,
            resolution: '1920*1080',
          },
        };

        const rawScreens =
          Array.isArray(template.value.screens) &&
          template.value.screens.length > 0
            ? template.value.screens
            : [];

        interface LooseScreen {
          screenId: unknown;
          screenName?: unknown;
        }

        const resolveScreenId = (screen: LooseScreen): number => {
          if (typeof screen.screenId === 'number') return screen.screenId;

          if (typeof screen.screenId === 'string') {
            const raw = screen.screenId.trim();
            if (!raw) throw new TypeError('screenId is empty');

            const asNumber = Number(raw);
            if (!Number.isNaN(asNumber)) return asNumber;

            const slug = raw.toLowerCase();
            if (slug === 'live-status') return 33;
            if (slug === 'edashboard') return 32;
          }

          const name = coerceLowerString(
            coerceTrimmedString(screen.screenName),
          );
          if (name === 'live status') return 33;
          if (name === 'edashboard') return 32;

          const found = screenCatalog.value.find(
            (item) =>
              coerceLowerString(coerceTrimmedString(item.screenName)) === name,
          );
          if (found) return found.screenId;

          const screenIdText =
            coerceTrimmedString(screen.screenId) || '<invalid>';
          const screenNameText =
            coerceTrimmedString(screen.screenName) || '<invalid>';
          throw new TypeError(
            `Unknown screenId/screenName: ${screenIdText} / ${screenNameText}`,
          );
        };

        const dto: CreateTemplateDto = {
          createdBy: template.value.createdBy,
          default: template.value.default ?? false,
          devices,
          id: template.value.id || undefined,
          label: template.value.label,
          plant,
          scopeList: Array.isArray(template.value.scopeList)
            ? template.value.scopeList
            : [],
          screens: rawScreens.map((s) => {
            const incoming = s as unknown as LooseScreen;
            const screenId = resolveScreenId(incoming);
            const incomingName = coerceTrimmedString(incoming.screenName);
            return {
              screenId,
              screenName: incomingName || String(screenId),
            };
          }),
          status,
        };
        const response = await upsertTemplate(dto);
        const saved = response.data;
        if (saved?.id) {
          template.value.id = saved.id;
        }
        return { success: true, payload: template.value };
      } catch (error_: unknown) {
        error.value =
          error_ instanceof Error
            ? error_.message
            : 'Failed to submit template';
        return { success: false };
      } finally {
        loading.value = false;
      }
    }

    // --- Actions ---
    /**
     * Replaces the current template state.
     * @param newTemplate The template object to set as current.
     */
    function setTemplate(newTemplate: PageBuilderTemplate): void {
      // Defensive: ensure id is not lost when editing
      template.value = {
        ...newTemplate,
        id: newTemplate.id || template.value.id || '',
      };
    }

    // --- Coercion helpers are defined at module scope ---

    // --- Column inference helpers are defined at module scope ---

    /**
     * Maps a TemplateDto to an array of Section objects.
     * @param dto The template DTO to map.
     * @returns The array of Section objects.
     */
    function mapTemplateDtoToSections(dto: TemplateDto): Array<Section> {
      const layout = dto.devices?.desktop?.layout;
      const sectionDtos = Array.isArray(layout?.sections)
        ? layout.sections
        : [];
      const ordered = [...sectionDtos].sort(
        (a, b) => (a.order ?? 0) - (b.order ?? 0),
      );

      return ordered.map((sectionDto, index) => {
        const widgetDtos = Array.isArray(sectionDto.widgets)
          ? [...sectionDto.widgets]
          : [];
        widgetDtos.sort((a, b) => (a.order ?? 0) - (b.order ?? 0));

        const columnsCount = inferColumnsCountFromWidgets(widgetDtos);
        const columns: Array<SectionColumn> = Array.from(
          { length: columnsCount },
          (_, colIndex) => ({ id: `col_${colIndex}`, widgets: [] }),
        );

        for (const widgetDto of widgetDtos) {
          const colIndex = positionToColumnIndex(
            columnsCount,
            widgetDto.position,
          );
          const safeIndex = Math.max(0, Math.min(columns.length - 1, colIndex));
          columns[safeIndex].widgets.push({
            defId: widgetDto.component?.code ?? '',
            instanceId: widgetDto.id ?? newId('widget'),
            subtitle: widgetDto.component?.label ?? '',
            title: widgetDto.label ?? widgetDto.component?.label ?? '',
          });
        }

        return {
          columns,
          configSchema: sectionDto.configSchema ?? {},
          id: sectionDto.id ?? `section_${index}`,
          label: coerceTrimmedString(sectionDto.label),
          maxWidget: sectionDto.maxWidget ?? 0,
          minWidget: sectionDto.minWidget ?? 0,
          order: sectionDto.order ?? index,
          sideGroupId: readSideGroupIdFromConfigSchema(sectionDto.configSchema),
          widgets: [],
        };
      });
    }

    /**
     * Maps a TemplateDto to a PageBuilderTemplate object.
     * @param dto The template DTO to map.
     * @returns The PageBuilderTemplate object.
     */
    function mapTemplateDtoToBuilderTemplate(
      dto: TemplateDto,
    ): PageBuilderTemplate {
      const desktopLayout = dto.devices?.desktop?.layout;
      const width =
        typeof desktopLayout?.width === 'number' ? desktopLayout.width : 788;
      const height =
        typeof desktopLayout?.height === 'number' ? desktopLayout.height : 929;

      return {
        createdAt: dto.createdAt ?? '',
        createdBy: dto.createdBy ?? '',
        default: Boolean(dto.default),
        devices: {
          desktop: {
            layout: {
              height,
              sections: mapTemplateDtoToSections(dto),
              width,
            },
            resolution: dto.devices?.desktop?.resolution ?? '1920*1080',
          },
          mobile: {
            layout: dto.devices?.mobile?.layout ?? {},
            resolution: dto.devices?.mobile?.resolution ?? '',
          },
          tablet: {
            layout: dto.devices?.tablet?.layout ?? {},
            resolution: dto.devices?.tablet?.resolution ?? '',
          },
        },
        id: dto.id,
        label: dto.label ?? '',
        plant: dto.plant ?? 0,
        scopeList: Array.isArray(dto.scopeList) ? dto.scopeList : [],
        screens: Array.isArray(dto.screens) ? dto.screens : [],
        status: coerceTemplateStatus(dto.status),
        updatedAt: dto.updatedAt ?? '',
        updatedBy: dto.updatedBy ?? '',
      };
    }

    /**
     * Builds a PageBuilderTemplate from a TemplateDto.
     * @param dto The template DTO to build from.
     * @returns The constructed PageBuilderTemplate.
     */
    function buildTemplateFromDto(dto: TemplateDto): PageBuilderTemplate {
      return mapTemplateDtoToBuilderTemplate(dto);
    }

    /**
     * Maps a TemplateDto to a builder template.
     * @param dto The template DTO to map.
     */
    function setTemplateFromDto(dto: TemplateDto): void {
      setTemplate(mapTemplateDtoToBuilderTemplate(dto));
    }

    /**
     *
     */
    function clearTemplateToEdit(): void {
      templateToEdit.value = undefined;
    }

    /**
     * Loads a template by plant ID and template key.
     * @param plantId The plant ID to load the template for.
     * @param templateKey The template key to load.
     */
    async function loadTemplateByKey(
      plantId: number,
      templateKey: string,
    ): Promise<void> {
      loading.value = true;
      error.value = undefined;
      try {
        const dto = await getTemplate(plantId, templateKey);
        setTemplate(mapTemplateDtoToBuilderTemplate(dto));
      } catch (error_: unknown) {
        error.value =
          error_ instanceof Error ? error_.message : 'Failed to load template';
        throw error_;
      } finally {
        loading.value = false;
      }
    }
    // Save template (draft) via API
    /**
     * Saves the current template as a draft.
     * @returns The mock save result including success flag and optional payload.
     */
    async function saveTemplate(): Promise<{
      success: boolean;
      payload?: PageBuilderTemplate;
    }> {
      return submitTemplate('draft');
    }

    // Publish template via API
    /**
     * Publishes the current template.
     * @returns The mock publish result including success flag and optional payload.
     */
    async function publishTemplate(): Promise<{
      success: boolean;
      payload?: PageBuilderTemplate;
    }> {
      return submitTemplate('published');
    }

    /**
     * Resets the template to its default state.
     */
    function resetTemplate(): void {
      try {
        // Pinia-plugin-persistedstate typically uses the store id as key.
        // Some older setups use a 'pinia-' prefix; clear both defensively.
        localStorage.removeItem('template');
        localStorage.removeItem('pinia-template');
      } catch {
        // Ignore errors when clearing localStorage
      }
      template.value = createDefaultTemplate();
    }

    /**
     * Sets the available screens in the store.
     * @param screens The array of TemplateScreen objects to set as available.
     */
    function setAvailableScreens(screens: Array<TemplateScreen>): void {
      const incoming = (screens ?? []).filter((s) => {
        const sid = (s as { screenId?: unknown } | null | undefined)?.screenId;
        if (typeof sid === 'number') return Number.isFinite(sid);
        if (typeof sid === 'string') return sid.trim().length > 0;
        return false;
      });

      const byId = new Map(
        screenCatalog.value.map((s) => [normalizeScreenId(s.screenId), s]),
      );

      for (const s of incoming) {
        const key = normalizeScreenId(s.screenId);
        const existing = byId.get(key);
        if (existing) {
          existing.screenName =
            coerceTrimmedString(s.screenName) || existing.screenName;
          existing.enabled = true;
        } else {
          byId.set(key, {
            enabled: true,
            screenId: s.screenId,
            screenName: coerceTrimmedString(s.screenName) || String(s.screenId),
          });
        }
      }

      screenCatalog.value = [...byId.values()];
    }

    /**
     * Loads a template by input object.
     * @param input The input object containing plantId and screenOptionId.
     * @param input.plantId The plant ID to load the template for.
     * @param input.screenOptionId The screen option ID to load the template for.
     */
    function seedNewTemplate(input: {
      plantId: number;
      screenOptionId: string;
    }): void {
      const seed = {
        plantId: Number(input.plantId),
        screenOptionId: String(input.screenOptionId ?? ''),
      };
      newTemplateSeed.value = seed;
      localStorage.setItem(NEW_TEMPLATE_SEED_KEY, JSON.stringify(seed));
    }

    /**
     *
     */
    function applyNewTemplateSeed(): void {
      if (!newTemplateSeed.value) return;

      const plantId = Number(newTemplateSeed.value.plantId);
      if (Number.isFinite(plantId) && plantId > 0) {
        template.value.plant = plantId;
      }

      const optionId = String(
        newTemplateSeed.value.screenOptionId ?? '',
      ).trim();
      const resolved = optionId ? resolveScreensForOptionId(optionId) : [];
      if (resolved.length > 0) template.value.screens = resolved;

      newTemplateSeed.value = undefined;
      localStorage.removeItem(NEW_TEMPLATE_SEED_KEY);
    }

    /**
     * Updates a single field on the template.
     * @param key The field name to update.
     * @param value The value to assign.
     */
    function updateTemplateField<TKey extends keyof PageBuilderTemplate>(
      key: TKey,
      value: PageBuilderTemplate[TKey],
    ): void {
      template.value[key] = value;
    }

    // --- Getters for layout/rows ---
    // Compute rows from sections for rendering (max = layout.maxSection)
    const sectionRows = computed(() => {
      const { maxSection } = ensureDesktopLayout();
      const maxRows = typeof maxSection === 'number' ? maxSection : 4;
      const rows: Array<SectionRow> = [];
      const list = getSections();
      let index = 0;
      while (index < list.length && rows.length < maxRows) {
        const group: Array<Section> = [];
        const groupSideId = list[index].sideGroupId;
        group.push(list[index]);
        let nextIndex = index + 1;
        while (
          nextIndex < list.length &&
          list[nextIndex].sideGroupId &&
          list[nextIndex].sideGroupId === groupSideId
        ) {
          group.push(list[nextIndex]);
          nextIndex += 1;
        }
        rows.push({
          key: group.map((s) => s.id).join('-'),
          sections: group,
          showAddButton: rows.length < maxRows - 1,
        });
        index = nextIndex;
      }
      return rows;
    });

    // --- Section/Row/Widget Operations ---
    // Add a new section with specified columns
    /**
     * Adds a new section with the specified number of columns.
     * @param columnsCount The number of columns to create.
     */
    function addSection(columnsCount: number): void {
      const { maxSection } = ensureDesktopLayout();
      const maxRows = typeof maxSection === 'number' ? maxSection : 4;
      // Grouped (side-by-side) sections count as a single row.
      const currentRows = sectionRows.value.length;
      if (currentRows >= maxRows) return;

      const sections = getSections();
      const cols: Array<SectionColumn> = Array.from(
        { length: columnsCount },
        (_, index) => ({
          id: newId('col'),
          label: `Column ${index + 1}`,
          widgets: [],
        }),
      );
      const newSection: Section = {
        columns: cols,
        configSchema: {},
        id: newId('section'),
        label: '',
        maxWidget: 0,
        minWidget: 0,
        order: sections.length,
        sideGroupId: undefined,
        widgets: [],
      };
      setSections([...sections, newSection]);
    }

    // Add a side section next to anchor
    /**
     * Adds a side section next to an existing anchor section.
     * @param anchorSectionId The anchor section ID.
     */
    function addSideSection(anchorSectionId: string): void {
      const sections = getSections();
      const anchorIndex = sections.findIndex((s) => s.id === anchorSectionId);
      if (anchorIndex < 0) return;
      const anchor = sections[anchorIndex];
      const columnsCount = Math.max(1, anchor.columns.length);
      const groupId = anchor.sideGroupId ?? newId('sg');
      if (!anchor.sideGroupId) anchor.sideGroupId = groupId;
      const groupCount = sections.filter(
        (s) => s.sideGroupId === groupId,
      ).length;
      if (groupCount >= 2) return;
      let insertIndex = anchorIndex + 1;
      while (
        insertIndex < sections.length &&
        sections[insertIndex].sideGroupId === groupId
      ) {
        insertIndex += 1;
      }
      const colStart = 1;
      const cols: Array<SectionColumn> = Array.from(
        { length: columnsCount },
        (_, index) => ({
          id: newId('col'),
          label: `Column ${index + colStart}`,
          widgets: [],
        }),
      );
      const newSection: Section = {
        columns: cols,
        configSchema: {},
        id: newId('section'),
        label: '',
        maxWidget: 0,
        minWidget: 0,
        order: sections.length,
        sideGroupId: groupId,
        widgets: [],
      };
      sections.splice(insertIndex, 0, newSection);
      setSections([...sections]);
    }

    // Delete a section by ID
    /**
     * Deletes a section by ID.
     * @param sectionId The section ID to delete.
     */
    function deleteSection(sectionId: string): void {
      const sections = getSections();
      setSections(sections.filter((s) => s.id !== sectionId));
    }

    // Add a widget to a section column
    /**
     * Adds a widget instance to a section column.
     * @param sectionId The section ID.
     * @param colId The column ID.
     * @param widgetDefinition The widget definition to place.
     */
    function addWidget(
      sectionId: string,
      colId: string,
      widgetDefinition: WidgetDefinition,
    ): void {
      const sections = getSections();
      const section = sections.find((s) => s.id === sectionId);
      if (!section) return;
      const col = section.columns.find((c) => c.id === colId);
      if (!col) return;
      const newWidget: PlacedWidget = {
        defId: widgetDefinition.id,
        instanceId: newId('widget'),
        subtitle: widgetDefinition.subtitle,
        title: widgetDefinition.title,
      };
      col.widgets.push(newWidget);
      setSections([...sections]);
    }

    // Delete a widget from a column
    /**
     * Deletes a widget instance from a section column.
     * @param sectionId The section ID.
     * @param colId The column ID.
     * @param widgetId The widget instance ID.
     */
    function deleteWidget(
      sectionId: string,
      colId: string,
      widgetId: string,
    ): void {
      const sections = getSections();
      const section = sections.find((s) => s.id === sectionId);
      if (!section) return;
      const col = section.columns.find((c) => c.id === colId);
      if (!col) return;
      col.widgets = col.widgets.filter((w) => w.instanceId !== widgetId);
      setSections([...sections]);
    }
    // Move widget between columns/sections
    /**
     * Moves a widget between sections/columns.
     * @param payload Movement payload including source/target coordinates.
     */
    function moveWidget(payload: MoveWidgetPayload): void {
      const { fromSectionId, fromColId, fromIdx, toSectionId, toColId, toIdx } =
        payload;
      const sections = getSections();
      const fromSection = sections.find((s) => s.id === fromSectionId);
      const toSection = sections.find((s) => s.id === toSectionId);
      if (!fromSection || !toSection) return;
      const fromCol = fromSection.columns.find((c) => c.id === fromColId);
      const toCol = toSection.columns.find((c) => c.id === toColId);
      if (!fromCol || !toCol) return;
      const [moved] = fromCol.widgets.splice(fromIdx, 1);
      toCol.widgets.splice(toIdx, 0, moved);
      setSections([...sections]);
    }

    // Fetch widget/component definitions from API (mocked for now)
    /**
     * Fetches widget/component definitions.
     */
    async function fetchComponents(): Promise<void> {
      loading.value = true;
      error.value = undefined;
      try {
        const apiComponents = await fetchComponentsApi();
        // Map API result to local ComponentData structure if needed
        components.value = apiComponents.map((c) => {
          let configSchema: Record<string, unknown> = {};
          switch (c.code) {
            case 'target':
            case 'production': {
              configSchema = {
                container: { class: 'kpi-widget' },
                header: { class: 'kpi-header' },
                value: { class: 'kpi-value' },
              };
              break;
            }
            case 'delta': {
              configSchema = {
                container: { class: 'kpi-widget kpi-delta' },
                header: { class: 'kpi-header' },
                value: { class: 'kpi-value' },
              };
              break;
            }
            case 'event_timer': {
              configSchema = {
                container: { class: 'event-widget' },
                header: { class: 'event-header' },
                value: { class: 'event-value' },
              };
              break;
            }
            case 'reference_in_prod':
            case 'tool_in_prod': {
              configSchema = {
                container: { class: 'reference-widget' },
                header: { class: 'reference-header' },
                value: { class: 'reference-value' },
              };
              break;
            }
            case 'scrap':
            case 'rework': {
              configSchema = {
                container: { class: 'nonquality-widget' },
                header: { class: 'nonquality-header' },
                value: { class: 'nonquality-value' },
              };
              break;
            }
            default: {
              configSchema = {};
            }
          }
          return {
            apiLink: c.apiId?.url ?? '',
            apiMethod: '',
            apiParams: {},
            appListId: c.appsList ? c.appsList.split(',') : [],
            code: c.code,
            configSchema,
            description: c.description || '',
            id: c.componentId,
            label: c.label,
            scopeId: [],
            showLabel: c.showLabel,
            size: c.size,
            value: c.defaultValue,
          };
        });
      } catch (error_) {
        error.value =
          error_ instanceof Error
            ? error_.message
            : 'Failed to fetch components';
      } finally {
        loading.value = false;
      }
    }

    // --- Getters ---
    // List of all widget definitions
    const widgetDefs = computed<Array<WidgetDefinition>>(() =>
      components.value.map((comp) => ({
        id: comp.code,
        subtitle: comp.description,
        title: comp.label,
      })),
    );

    // Filtered widget definitions by search string
    /**
     * Filters widget definitions by a search string.
     * @param search The free-text search string.
     * @returns The filtered widget definitions.
     */
    function filteredWidgetDefs(search: string): Array<WidgetDefinition> {
      const q = search.trim().toLowerCase();
      if (!q) return widgetDefs.value;
      return widgetDefs.value.filter((w) =>
        `${w.title} ${w.subtitle}`.toLowerCase().includes(q),
      );
    }

    // --- Expose state, actions, getters ---
    return {
      // Section/row/widget operations (sorted)
      addSection,
      addSideSection,
      addWidget,
      applyNewTemplateSeed,
      availableScreens,
      buildTemplateFromDto,
      clearTemplateToEdit,
      components,
      deleteSection,
      deleteWidget,
      error,
      fetchComponents,
      filteredWidgetDefs,
      loadTemplateByKey,
      loading,
      moveWidget,
      publishTemplate,
      resetTemplate,
      resolveScreensForOptionId,
      saveTemplate,
      screenOptions,
      sectionRows,
      seedNewTemplate,
      setAvailableScreens,
      setTemplate,
      setTemplateFromDto,
      template,
      templateToEdit,
      updateTemplateField,
      widgetApiMap,
      widgetDefs,
    };
  },
  {
    persist: true,
  },
);

