export interface PreviewValidationResult {
  valid: boolean;
  message?: string;
}

type AnySection = Section | TemplateSection;

interface SectionValidationOutcome {
  valid: boolean;
  message?: string;
  widgetCount: number;
}

/**
 * Normalizes a label-like value into a non-empty string.
 * @param value The raw label value.
 * @param fallback The fallback label to use when the value is empty.
 * @returns The normalized label.
 */
function normalizeLabel(value: unknown, fallback: string): string {
  const v = typeof value === 'string' ? value.trim() : '';
  return v.length > 0 ? v : fallback;
}

/**
 * Creates an invalid section validation outcome.
 * @param message The reason the section is invalid.
 * @returns The invalid validation outcome.
 */
function invalidSection(message: string): SectionValidationOutcome {
  return { valid: false, message, widgetCount: 0 };
}

/**
 * Creates a valid section validation outcome.
 * @param widgetCount The number of widgets found in the section.
 * @returns The valid validation outcome.
 */
function validSection(widgetCount: number): SectionValidationOutcome {
  return { valid: true, widgetCount };
}

/**
 * Validates a single widget slot inside a builder section.
 * @param options Validation inputs.
 * @param options.widget The widget slot value to validate.
 * @param options.sectionLabel The label of the section, used for error messages.
 * @param options.usedWidgetDefinitions Set of widget definition ids already used in the layout.
 * @param options.rowSectionsCount The number of side-by-side sections in the current row.
 * @param options.columnsCount The number of columns in the current section.
 * @returns A validation outcome when invalid; otherwise undefined.
 */
function validateBuilderWidget(options: {
  widget: unknown;
  sectionLabel: string;
  usedWidgetDefinitions: Set<string>;
  rowSectionsCount: number;
  columnsCount: number;
}): SectionValidationOutcome | undefined {
  const {
    widget,
    sectionLabel,
    usedWidgetDefinitions,
    rowSectionsCount,
    columnsCount,
  } = options;

  const w = widget as { title?: unknown; defId?: unknown } | null | undefined;
  if (!w?.title || !w?.defId) {
    return invalidSection(
      `Section "${sectionLabel}" has an unfilled widget slot.`,
    );
  }

  let definitionId = '';
  if (typeof w.defId === 'string') definitionId = w.defId.trim();
  else if (typeof w.defId === 'number' || typeof w.defId === 'boolean') {
    definitionId = String(w.defId).trim();
  }

  if (!definitionId) {
    return invalidSection(
      `Section "${sectionLabel}" has an unfilled widget slot.`,
    );
  }

  if (usedWidgetDefinitions.has(definitionId)) {
    return invalidSection(
      'The same widget cannot be added more than once in the layout.',
    );
  }
  usedWidgetDefinitions.add(definitionId);

  const widgetTitle = normalizeLabel(w.title, 'Widget');
  const widgetSize = getWidgetSize(definitionId);

  if (widgetSize === 1 && (rowSectionsCount !== 1 || columnsCount !== 1)) {
    return invalidSection(
      `"${widgetTitle}" (full) can only be placed in a single-section row with a single-column section.`,
    );
  }

  if (widgetSize === 2 && columnsCount === 3) {
    return invalidSection(
      `"${widgetTitle}" (half) can only be placed in 1- or 2-column sections.`,
    );
  }

  return undefined;
}

/**
 * Checks if a section is a builder Section.
 * @param section The section to check.
 * @returns True if the section is a builder Section.
 */
function isBuilderSection(section: AnySection): section is Section {
  return (
    section !== undefined &&
    typeof section === 'object' &&
    'columns' in section &&
    Array.isArray((section as { columns?: unknown }).columns)
  );
}

/**
 * Counts the number of rows from the given sections.
 * @param sections The array of sections to count rows from.
 * @returns The number of rows.
 */
function countRowsFromSections(sections: Array<AnySection>): number {
  let rows = 0;
  let index = 0;
  while (index < sections.length) {
    const current = sections[index];
    const groupSideId = isBuilderSection(current)
      ? current.sideGroupId
      : undefined;
    rows += 1;

    let nextIndex = index + 1;
    while (
      nextIndex < sections.length &&
      isBuilderSection(sections[nextIndex]) &&
      Boolean((sections[nextIndex] as Section).sideGroupId) &&
      (sections[nextIndex] as Section).sideGroupId === groupSideId
    ) {
      nextIndex += 1;
    }

    index = nextIndex;
  }
  return rows;
}

/**
 * Builds a map of section IDs to their row counts.
 * @param sections The array of sections to process.
 * @returns A map where keys are section IDs and values are row counts.
 */
function buildRowSectionCounts(
  sections: Array<AnySection>,
): Map<string, number> {
  const counts = new Map<string, number>();
  let index = 0;
  while (index < sections.length) {
    const current = sections[index];
    const groupSideId = isBuilderSection(current)
      ? current.sideGroupId
      : undefined;

    const rowGroup: Array<AnySection> = [current];
    let nextIndex = index + 1;
    while (
      nextIndex < sections.length &&
      isBuilderSection(sections[nextIndex]) &&
      Boolean((sections[nextIndex] as Section).sideGroupId) &&
      (sections[nextIndex] as Section).sideGroupId === groupSideId
    ) {
      rowGroup.push(sections[nextIndex]);
      nextIndex += 1;
    }

    const rowSize = rowGroup.length;
    for (const s of rowGroup) {
      if (isBuilderSection(s) && typeof s.id === 'string') {
        counts.set(s.id, rowSize);
      }
    }

    index = nextIndex;
  }
  return counts;
}

