/**
 * Validates widgets inside a builder section (drag/drop layout).
 * @param options The validation options.
 * @param options.section The builder section to validate.
 * @param options.sectionLabel The display label used in error messages.
 * @param options.usedWidgetDefinitions Global set to enforce widget uniqueness.
 * @param options.rowSectionsCount The number of side-by-side sections in the row.
 * @param options.columnsCount The number of columns for this section.
 * @returns The validation outcome, including widget count when valid.
 */
function validateBuilderSectionWidgets(options: {
  section: Section;
  sectionLabel: string;
  usedWidgetDefinitions: Set<string>;
  rowSectionsCount: number;
  columnsCount: number;
}): SectionValidationOutcome {
  const { section, sectionLabel, usedWidgetDefinitions, rowSectionsCount } =
    options;

  const columns = Array.isArray(section.columns) ? section.columns : [];
  const { columnsCount } = options;
  let widgetCount = 0;

  for (const col of columns) {
    const widgets = Array.isArray(col.widgets) ? col.widgets : [];
    if (widgets.length === 0) {
      return invalidSection(
        `Section "${sectionLabel}" has an empty column. Each column must have at least one widget.`,
      );
    }

    for (const widget of widgets) {
      const widgetOutcome = validateBuilderWidget({
        columnsCount,
        rowSectionsCount,
        sectionLabel,
        usedWidgetDefinitions,
        widget,
      });
      if (widgetOutcome) return widgetOutcome;

      widgetCount += 1;
    }
  }

  return validSection(widgetCount);
}

/**
 * Validates widgets inside a template section (API DTO layout).
 * @param options The validation options.
 * @param options.section The template section to validate.
 * @param options.sectionLabel The display label used in error messages.
 * @param options.usedWidgetDefinitions Global set to enforce widget uniqueness.
 * @returns The validation outcome, including widget count when valid.
 */
function validateTemplateSectionWidgets(options: {
  section: TemplateSection;
  sectionLabel: string;
  usedWidgetDefinitions: Set<string>;
}): SectionValidationOutcome {
  const { section, sectionLabel, usedWidgetDefinitions } = options;

  const widgets = Array.isArray(section.widgets) ? section.widgets : [];
  if (widgets.length === 0) {
    return invalidSection(`Section "${sectionLabel}" has no widgets.`);
  }

  let widgetCount = 0;
  for (const widget of widgets) {
    const title = String(widget?.label ?? '').trim();
    const definitionId = String(widget?.component?.code ?? '').trim();
    if (!title || !definitionId) {
      return invalidSection(
        `Section "${sectionLabel}" has an unfilled widget slot.`,
      );
    }

    if (usedWidgetDefinitions.has(definitionId)) {
      return invalidSection(
        'The same widget cannot be added more than once in the layout.',
      );
    }
    usedWidgetDefinitions.add(definitionId);
    widgetCount += 1;
  }

  return validSection(widgetCount);
}

/**
 * Validates the preview of a page builder template.
 * @param template The page builder template to validate.
 * @returns The validation result, including validity and an optional message.
 */
export function validatePreview(
  template: PageBuilderTemplate,
): PreviewValidationResult {
  const layout = template?.devices?.desktop?.layout;
  const minSection =
    typeof layout?.minSection === 'number' ? layout.minSection : 3;
  const maxSection =
    typeof layout?.maxSection === 'number' ? layout.maxSection : 4;
  const sections = Array.isArray(layout?.sections)
    ? (layout.sections as Array<AnySection>)
    : [];

  const usedWidgetDefinitions = new Set<string>();

  const rowSectionCounts = buildRowSectionCounts(sections);

  // Grouped side-by-side sections (same sideGroupId) render as a single row.
  // Min/max constraints are defined in terms of rows.
  const rowCount = countRowsFromSections(sections);

  if (rowCount < minSection) {
    return {
      valid: false,
      message: `At least ${minSection} sections (rows) are required.`,
    };
  }
  if (rowCount > maxSection) {
    return {
      valid: false,
      message: `No more than ${maxSection} sections (rows) are allowed.`,
    };
  }

  for (const [sectionIndex, section] of sections.entries()) {
    const sectionLabel = normalizeLabel(
      (section as { label?: unknown })?.label,
      `Section ${sectionIndex + 1}`,
    );

    const outcome = isBuilderSection(section)
      ? validateBuilderSectionWidgets({
          columnsCount: Array.isArray(section.columns)
            ? section.columns.length
            : 0,
          rowSectionsCount: rowSectionCounts.get(section.id) ?? 1,
          section,
          sectionLabel,
          usedWidgetDefinitions,
        })
      : validateTemplateSectionWidgets({
          section,
          sectionLabel,
          usedWidgetDefinitions,
        });

    if (!outcome.valid) {
      return { valid: false, message: outcome.message };
    }

    const { widgetCount } = outcome;

    const minWidget = Number(
      (section as { minWidget?: unknown })?.minWidget ?? 0,
    );
    const maxWidget = Number(
      (section as { maxWidget?: unknown })?.maxWidget ?? 0,
    );

    if (minWidget && widgetCount < minWidget) {
      return {
        valid: false,
        message: `Section "${sectionLabel}" requires at least ${minWidget} widgets.`,
      };
    }
    if (maxWidget && widgetCount > maxWidget) {
      return {
        valid: false,
        message: `Section "${sectionLabel}" allows at most ${maxWidget} widgets.`,
      };
    }
  }
  return { valid: true };
}

import type { Section } from '../types/builder.types';

const PB_META_KEY = '__pb';

type PlainObject = Record<string, unknown>;

/**
 * Checks if a value is a plain object (not an array).
 * @param value The value to check.
 * @returns True if the value is a plain object, false otherwise.
 */
function isPlainObject(value: unknown): value is PlainObject {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Reads a persisted sideGroupId from a backend section configSchema.
 * Supports both { sideGroupId: string } and { __pb: { sideGroupId: string } }.
 * @param schema The config schema object to read from.
 * @returns The sideGroupId if found, otherwise undefined.
 */
export function readSideGroupIdFromConfigSchema(
  schema: unknown,
): string | undefined {
  if (!isPlainObject(schema)) return undefined;

  const direct = schema.sideGroupId;
  if (typeof direct === 'string' && direct.trim().length > 0) return direct;

  const meta = schema[PB_META_KEY];
  if (!isPlainObject(meta)) return undefined;

  const nested = meta.sideGroupId;
  if (typeof nested === 'string' && nested.trim().length > 0) return nested;

  return undefined;
}

/**
 * Writes sideGroupId into a configSchema object that will be persisted by the backend.
/**
 * Writes sideGroupId into a configSchema object that will be persisted by the backend.
 * Uses a namespaced key (__pb) to avoid collisions with real config schema fields.
 * @param currentSchema The current config schema object to update.
 * @param sideGroupId The sideGroupId to write.
 * @returns The updated config schema object with the sideGroupId set.
 */
export function writeSideGroupIdToConfigSchema(
  currentSchema: unknown,
  sideGroupId: Section['sideGroupId'],
): PlainObject {
  const base: PlainObject = isPlainObject(currentSchema)
    ? { ...currentSchema }
    : {};

  const currentMeta = base[PB_META_KEY];
  const meta: PlainObject = isPlainObject(currentMeta)
    ? { ...currentMeta }
    : {};

  if (typeof sideGroupId === 'string' && sideGroupId.trim().length > 0) {
    meta.sideGroupId = sideGroupId;
    base[PB_META_KEY] = meta;
  } else {
    delete meta.sideGroupId;
    if (Object.keys(meta).length === 0) {
      delete base[PB_META_KEY];
    } else {
      base[PB_META_KEY] = meta;
    }
  }

  return base;
}

