 * @param widgetDefinitionId The widget definition ID.
 * @returns The widget component.
 */
export function getWidgetComponent(widgetDefinitionId: string): Component {
  if (widgetDefinitionId === '__unused__') {
    // Intentionally ignored: widget component currently does not vary by ID.
  }
  return defineAsyncComponent(() => import('../components/widgets/widget.vue'));
}

// Helper to get widget size (1=full, 2=half, 3=not full)
/**
 * Gets the widget size.
 * @param widgetDefinitionId The widget definition ID.
 * @returns The widget size.
 */
export function getWidgetSize(widgetDefinitionId: string): number {
  const templateStore = useTemplateStore();
  const widget = templateStore.widgetApiMap[widgetDefinitionId]?.widget;
  if (!widget) return 1;
  if (widget.size === 'full') return 1;
  if (widget.size === 'half') return 2;
  if (widget.size === 'not full') return 3;
  if (widget.size === 'third') return 3;
  if (widget.size === 'thirds') return 3;
  return 1;
}

// Helper to get widget config
/**
 * Gets the widget configuration for a widget definition.
 * @param widgetDefinitionId The widget definition ID.
 * @returns The widget configuration, if available.
 */
export function getWidgetConfig(
  widgetDefinitionId: string,
): ComponentData | undefined {
  const templateStore = useTemplateStore();
  return templateStore.widgetApiMap[widgetDefinitionId]?.widget;
}

/**
 * Checks if a widget can be placed in a given section/column, and returns a rule result.
 * @param widgetDefinitionId The widget definition ID.
 * @param section The target section object. Should have id and columns properties.
 * @param section.id The ID of the section.
 * @param section.columns The columns array of the section.
 * @param col The target column object. Should have id and widgets properties.
 * @param col.id The ID of the column.
 * @param col.widgets The widgets array of the column.
 * @param sectionRows The array of section rows (for row grouping).
 * @returns Rule result indicating if widget placement is allowed and an optional message.
 */
export function getWidgetPlacementRule(
  widgetDefinitionId: string,
  section: {
    id: string;
    columns: Array<{ id: string; widgets: Array<{ id: string }> }>;
  },
  col: { id: string; widgets: Array<{ id: string }> },
  sectionRows: Array<{ sections: Array<{ id: string }> }> = [], // The array of section rows for row grouping
): { allowed: boolean; message?: string } {
  // Returns rule result indicating if widget placement is allowed and an optional message
  if (!section || !col) return { allowed: false, message: 'Invalid target.' };
  if (col.widgets.length > 0) {
    return { allowed: false, message: 'This column already has a widget.' };
  }
  // Prevent adding the same widget more than once in the section (any column)
  const alreadyExists = section.columns.some((column) =>
    column.widgets.some((w) => w.id === widgetDefinitionId),
  );
  const widgetConfig = getWidgetConfig(widgetDefinitionId);
  const widgetLabel = widgetConfig?.label || 'Widget';
  if (alreadyExists) {
    return {
      allowed: false,
      message: `"${widgetLabel}" cannot be added more than once in the same section.`,
    };
  }
  const widgetSize = getWidgetSize(widgetDefinitionId);
  const columnsCount = Array.isArray(section.columns)
    ? section.columns.length
    : 0;
  const row = sectionRows.find(
    (r) =>
      Array.isArray(r.sections) && r.sections.some((s) => s.id === section.id),
  );
  const rowSectionsCount = row?.sections?.length ?? 1;
  if (widgetSize === 1) {
    if (rowSectionsCount !== 1 || columnsCount !== 1) {
      return {
        allowed: false,
        message: `"${widgetLabel}" can only be placed in a single-section row with a single-column section.`,
      };
    }
  } else if (widgetSize === 2 && columnsCount === 3) {
    return {
      allowed: false,
      message: `"${widgetLabel}" can only be placed in 1- or 2-column sections.`,
    };
  }
  return { allowed: true };
}

