export const useHierarchyStore = defineStore(
  'hierarchy',
  () => {
    // State
    const plant = ref<string>('');
    const productionLine = ref<string>('');
    const resource = ref<string>('');
    const uap = ref<string>('');
    const workcenter = ref<string>('');

    // Actions
    /**
     *
     * @param payload necessary elements of hierarchy
     */
    function setHierarchy(payload: HierarchyPayload): void {
      plant.value = payload.plant;
      productionLine.value = payload.productionLine;
      resource.value = payload.resource;
      uap.value = payload.uap;
      workcenter.value = payload.workcenter;
    }

    /**
     *
     */
    function resetHierarchy(): void {
      plant.value = '';
      productionLine.value = '';
      resource.value = '';
      uap.value = '';
      workcenter.value = '';
    }

    return {
      plant,
      productionLine,
      resetHierarchy,
      resource,
      setHierarchy,
      uap,
      workcenter,
    };
  },
  {
    persist: true,
  },
);

