        `${adminUrl}/routings/${routingId}/materials/${encodeURIComponent(materialId)}?plant=${plant}`,
        {},
        { headers: getHeaders() },
      );
    } catch (error) {
      appLogger.error(
        `Failed to unassign material ${materialId} from routing ${routingId}: ${String(error)}`,
      );
      throw error;
    }
  }

  // Operations
  public static async listMaterials(
    routingId: number | undefined,
    plant: number,
  ): Promise<MaterialsResponse> {
    try {
      const url = routingId
        ? `${adminUrl}/routings/${routingId}/materials?plant=${encodeURIComponent(String(plant))}`
        : `${adminUrl}/admin/getAllMaterial/${encodeURIComponent(String(plant))}`;
      const response: AxiosResponse = await axios.get(url, {
        headers: getHeaders(),
      });
      return response.data;
    } catch (error) {
      appLogger.error(
        routingId
          ? `Failed to list materials for routing ${routingId}: ${String(error)}`
          : `Failed to list available materials: ${String(error)}`,
      );
      throw error;
    }
  }

  public static async getOperationById(
    routingId: number,
    operationId: number,
  ): Promise<Operation> {
    try {
      const response: AxiosResponse = await axios.get(
        `${adminUrl}/routings/${routingId}/operations/${operationId}`,
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(
        `Failed to get operation ${operationId}: ${String(error)}`,
      );
      throw error;
    }
  }

  public static async createOperation(
    dto: CreateOperationDto,
  ): Promise<Operation> {
    try {
      const response: AxiosResponse = await axios.post(
        `${adminUrl}/routings/${dto.routingId}/operations`,
        {
          operationName: dto.operationName,
          operationTypeId: dto.operationTypeId,
        },
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(
        `Failed to create operation for routing ${dto.routingId}: ${String(error)}`,
      );
      throw error;
    }
  }

  public static async updateOperation(
    routingId: number,
    opId: number,
    dto: UpdateOperationDto,
  ): Promise<Operation> {
    try {
      const response: AxiosResponse = await axios.put(
        `${adminUrl}/routings/${routingId}/operations/${opId}`,
        dto,
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(`Failed to update operation ${opId}: ${String(error)}`);
      throw error;
    }
  }

  public static async removeOperation(
    routingId: number,
    opId: number,
  ): Promise<void> {
    try {
      await axios.delete(
        `${adminUrl}/routings/${routingId}/operations/${opId}`,
        { headers: getHeaders() },
      );
    } catch (error) {
      appLogger.error(`Failed to delete operation ${opId}: ${String(error)}`);
      throw error;
    }
  }

  public static async reorderOperations(
    routingId: number,
    payload: { routingOperationIds: Array<number> },
  ): Promise<Array<Operation>> {
    try {
      const response: AxiosResponse = await axios.post(
        `${adminUrl}/routings/${routingId}/operations/reorder`,
        payload,
        { headers: getHeaders() },
      );
      return response.data;
    } catch (error) {
      appLogger.error(
        `Failed to reorder operations for routing ${routingId}: ${String(error)}`,
      );
      throw error;
    }
  }
}

