import { defineStore } from 'pinia';
import { ref } from 'vue';
import { RoutingDto } from '../dto/routing.dto';

interface PendingOperation {
  routingOperationId: number;
  operationName: string;
  operationTypeId: number;
  operationTypeName: string;
}

interface PendingOperationUpdate {
  operationName: string;
  operationTypeId: number;
  operationTypeName: string;
}

export const useRoutingStore = defineStore(
  'routing',
  () => {
    const loading = ref(false);
    const routings = ref<Array<RoutingDto>>([]);
    const selectedRouting = ref<RoutingDto | undefined>(undefined);
    // Local pending changes used to stage modifications before committing on Save
    const pendingOperations = ref<Array<PendingOperation>>([]); // New operations to create
    const pendingUpdatedOperations = ref<
      Record<number, PendingOperationUpdate>
    >({}); // Updates keyed by operation id
    const pendingDeletedOperationIds = ref<Array<number>>([]); // Operation ids to delete on save
    // Pending material assignments/unassignments (staged until save)
    const pendingAssignedMaterials = ref<Array<string>>([]);
    const pendingUnassignedMaterials = ref<Array<string>>([]);

    return {
      loading,
      // Pending change buffers (staging area)
      pendingAssignedMaterials,
      pendingDeletedOperationIds,
      pendingOperations,
      pendingUnassignedMaterials,
      pendingUpdatedOperations,
      routings,
      selectedRouting,
    };
  },
  {
    persist: {
      paths: ['selectedRouting'], // Persist selectedRouting across page reloads
    },
  },
);

