export const getDynamicActions = async (
  appName: string,
  roles: string,
): Promise<Array<Permission>> => {
  try {
    // Make the API request to the backend
    const response = await axios.get(
      `${umeBaseUrl}/permission-definition/${appName}`,
      {
        headers: {
          authorization: `Bearer ${token}`,
        },
        params: {
          roles, // Pass roles as a query parameter
        },
      },
    );

    // Extract the permissions data from the response
    const permissions: Array<Permission> = response.data;

    // Return the permissions in the required format
    return permissions.map((permission) => ({
      actionType: permission.actionType,
      object: permission.object,
    }));
  } catch (error) {
    console.error('Error fetching dynamic actions:', error);
    return []; // Return an empty array on error
  }
};

